export function rotateRight<T>(a: readonly T[], k: number): T[] {
  const n = a.length;

  // Handle empty array
  if (n === 0) {
    return [];
  }

  // Normalize k to handle negative and large values
  // For negative k, rotate left: equivalent to rotating right by (n - |k| mod n)
  // For positive k, rotate right normally
  const normalizedK = ((k % n) + n) % n;

  // If normalizedK is 0, return a copy of the original array
  if (normalizedK === 0) {
    return [...a];
  }

  // Rotate right by normalizedK: take last normalizedK elements and put them in front
  const rightPart = a.slice(n - normalizedK);
  const leftPart = a.slice(0, n - normalizedK);

  return [...rightPart, ...leftPart];
}
