export function lowerBound(a: readonly number[], x: number): number {
  // Handle empty array case
  if (a.length === 0) {
    return 0;
  }

  let left = 0;
  let right = a.length;

  while (left < right) {
    const mid = Math.floor((left + right) / 2);

    // Use strict inequality to find first element >= x
    if (a[mid] < x) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  // Post-condition: left is the first index where a[left] >= x, or a.length if no such index
  return left;
}
